export type ChatStreamEvent =
  | { event: "turnStarted"; data: { turnId: string; userMessageId: string } }
  | { event: "assistantDelta"; data: { turnId: string; delta: string } }
  | { event: "toolCallStarted"; data: { turnId: string; toolCallId: string; toolCode: string } }
  | {
      event: "toolCallCompleted";
      data: {
        turnId: string;
        toolCallId: string;
        toolCode: string;
        status: "applied" | "pending_confirmation" | "rejected" | string;
        hasAppliedWrite: boolean;
      };
    }
  | {
      event: "workingStateUpdated";
      data: {
        turnId: string;
        progress: ProgressSummaryDto;
        pendingPatchCount: number;
      };
    }
  | {
      event: "turnCompleted";
      data: {
        turnId: string;
        assistantMessageId: string;
        sealedVersion?: DraftVersionSummaryDto | null;
      };
    }
  | { event: "turnError"; data: { turnId: string; error: IpcError } };

export type WorkflowProgressEvent =
  | {
      event: "workflowStarted";
      data: {
        workflowRunId: string;
        planGeneration: number;
        phase: number;
        subphase?: number | null;
        totalRounds: number;
        totalTasks: number;
      };
    }
  | {
      event: "roundStarted";
      data: {
        workflowRunId: string;
        roundIndex: number;
        activeTaskIdentities: string[];
      };
    }
  | {
      event: "taskCompleted";
      data: {
        workflowRunId: string;
        taskIdentity: string;
        completedTasks: number;
        totalTasks: number;
        wasSkippedByReceipt: boolean;
      };
    }
  | {
      event: "roundSealed";
      data: {
        workflowRunId: string;
        roundIndex: number;
        sealedVersion?: DraftVersionSummaryDto | null;
        progress: ProgressSummaryDto;
      };
    }
  | { event: "cancelRequested"; data: { workflowRunId: string } }
  | {
      event: "workflowFinished";
      data: {
        workflowRunId: string;
        status: "completed" | "cancelled" | "failed" | string;
        lastSealedVersion?: DraftVersionSummaryDto | null;
      };
    };

export type SceneGenerationStreamEvent =
  | {
      event: "started";
      data: {
        requestId: string;
        generationId: string;
        sceneId: string;
        baselineVersionNumber: number;
        authorizationValid: boolean;
        status: GenerationStreamStatus;
      };
    }
  | {
      event: "delta";
      data: {
        requestId: string;
        generationId: string;
        sceneId: string;
        textDelta: string;
        authorizationValid: boolean;
      };
    }
  | {
      event: "completed";
      data: {
        requestId: string;
        generationId: string;
        sceneId: string;
        baselineVersionNumber: number;
        fullText: string;
        authorizationValid: boolean;
        status: GenerationStreamStatus;
      };
    }
  | {
      event: "cancelled";
      data: {
        requestId: string;
        generationId: string;
        sceneId: string;
        partialText: string;
        authorizationValid: boolean;
        status: GenerationStreamStatus;
      };
    }
  | {
      event: "invalidatedByLock";
      data: {
        requestId: string;
        generationId: string;
        sceneId: string;
        partialText: string;
        authorizationValid: boolean; // Always false
        status: GenerationStreamStatus;
      };
    }
  | {
      event: "failed";
      data: {
        requestId: string;
        generationId: string;
        sceneId: string;
        error: IpcError;
        authorizationValid: boolean;
        status: GenerationStreamStatus;
      };
    };

